情节记忆存储具体的历史事件，便于 Agent 回顾过去的交互： class EpisodicMemory: """存储具体事件和经验""" def record_episode(self, task: str, actions: list, outcome: str, success: bool): """记录一次任务执行经历""" episode = { "task": task, "actions_taken": actions, "outcome": outcome, "success": success, "learned": self._extract_lesson(task, actions, outcome, success) } self.memory.store( content=f"任务：{task}
结果：{outcome}
经验：{episode['learned']}", memory_type="episode", metadata={"success": success} ) def _extract_lesson(self, task, actions, outcome, success) -> str: response = client.chat.completions.create( model="gpt-4o-mini", messages=[{"role": "user", "content": f"从这次任务经验中提炼关键教训（一句话）：
任务：{task}
动作：{actions}
结果：{outcome}
是否成功：{success}"}] ) return response.choices[0].message.content

ToT 将推理过程建模为树状搜索，探索多条推理路径并选择最优： from dataclasses import dataclass from typing import Optional @dataclass class ThoughtNode: thought: str score: float children: list['ThoughtNode'] parent: Optional['ThoughtNode'] = None def tree_of_thoughts(problem: str, breadth: int = 3, depth: int = 4) -> str: """ 广度优先展开思维树 breadth: 每步生成多少个候选思路 depth: 最大思考深度 """ def generate_thoughts(state: str, n: int) -> list[str]: """生成 n 个候选下一步思路""" response = client.chat.completions.create( model="gpt-4o", messages=[{ "role": "user", "content": f"针对以下问题和当前推理状态，生成 {n} 个不同的下一步思路（JSON格式）：
问题：{problem}
当前状态：{state}" }], response_format={"type": "json_object"} ) return json.loads(response.choices[0].message.content)["thoughts"] def evaluate_thought(thought: str) -> float: """评估思路的前景分数（0-1）""" response = client.chat.completions.create( model="gpt-4o-mini", messages=[{ "role": "user", "content": f"评估以下思路解决问题的可能性，返回 0-1 的分数：
问题：{problem}
思路：{thought}" }] ) return float(response.choices[0].message.content.strip()) # BFS 展开 current_level = [ThoughtNode(thought=problem, score=1.0, children=[])] for d in range(depth): next_level = [] for node in current_level: thoughts = generate_thoughts(node.thought, breadth) for t in thoughts: score = evaluate_thought(t) child = ThoughtNode(thought=t, score=score, children=[], parent=node) node.children.append(child) next_level.append(child) # 保留评分最高的节点继续展开 next_level.sort(key=lambda x: x.score, reverse=True) current_level = next_level[:breadth] # 返回评分最高的完整推理链 best_node = max(current_level, key=lambda x: x.score) return best_node.thought

在异步 Web 框架（FastAPI、aiohttp）中，使用 async 生成器处理流式输出： from openai import AsyncOpenAI from typing import AsyncGenerator client = AsyncOpenAI() async def stream_tokens(prompt: str) -> AsyncGenerator[str, None]: """异步生成器，适用于 FastAPI 等异步框架""" stream = await client.chat.completions.create( model="gpt-4o", messages=[{"role": "user", "content": prompt}], stream=True ) async for chunk in stream: content = chunk.choices[0].delta.content if content: yield content # FastAPI 流式端点 from fastapi import FastAPI from fastapi.responses import StreamingResponse app = FastAPI() @app.post("/chat/stream") async def chat_stream(request: ChatRequest): async def generate(): async for token in stream_tokens(request.message): # SSE 格式 yield f"data: {json.dumps({'content': token})}

" yield "data: [DONE]

" return StreamingResponse( generate(), media_type="text/event-stream", headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"} )
